import{_ as a,o,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"Princípios Éticos de Almas Gêmeas","description":"","frontmatter":{},"headers":[],"relativePath":"pt/58-双魂伦理准则.md","filePath":"pt/58-双魂伦理准则.md"}'),d={name:"pt/58-双魂伦理准则.md"};function t(r,e,n,l,m,c){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="principios-eticos-de-almas-gemeas" tabindex="-1">Princípios Éticos de Almas Gêmeas <a class="header-anchor" href="#principios-eticos-de-almas-gemeas" aria-label="Permalink to &quot;Princípios Éticos de Almas Gêmeas&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>58</td></tr><tr><td>Módulo</td><td>Raças e Formas de Vida</td></tr><tr><td>Palavras-chave Principais</td><td>Ética de almas gêmeas, direitos de personalidade, dignidade da alma, equilíbrio de interesses, revisão ética</td></tr></tbody></table><h2 id="i-apresentacao-do-problema-etico-de-almas-gemeas" tabindex="-1">I. Apresentação do Problema Ético de Almas Gêmeas <a class="header-anchor" href="#i-apresentacao-do-problema-etico-de-almas-gemeas" aria-label="Permalink to &quot;I. Apresentação do Problema Ético de Almas Gêmeas&quot;">​</a></h2><p>O problema ético de almas gêmeas é o problema ético fundamental que a civilização de simbiose âncora deve responder ao enfrentar o corpo de substituição das trevas (consulte &quot;57-Origem e Essência do Corpo de Substituição das Trevas&quot;). Quando existem duas almas independentes em um mesmo corpo — a alma do hospedeiro original e a alma de substituição das trevas —, uma série de profundos problemas éticos surge:</p><ul><li>As duas almas possuem ambas direitos de personalidade independentes?</li><li>Os direitos da alma do hospedeiro original têm prioridade sobre os da alma de substituição das trevas?</li><li>É ético eliminar a alma de substituição das trevas para proteger a alma do hospedeiro original?</li><li>Quando os interesses das duas almas entram em conflito, como deve ser o equilíbrio?</li><li>A sociedade tem a obrigação de investir recursos para salvar a alma do hospedeiro original substituída pelas trevas?</li><li>A alma de substituição das trevas possui um &quot;direito à vida&quot;?</li></ul><p>Esses problemas não têm respostas simples, exigindo o estabelecimento de princípios éticos sistemáticos para orientar a prática. Os &quot;Princípios Éticos de Almas Gêmeas&quot; são precisamente um documento normativo formulado para responder a esses problemas, servindo como base ética para a identificação, tratamento e descarte do corpo de substituição das trevas.</p><h2 id="ii-principios-fundamentais-da-etica-de-almas-gemeas" tabindex="-1">II. Princípios Fundamentais da Ética de Almas Gêmeas <a class="header-anchor" href="#ii-principios-fundamentais-da-etica-de-almas-gemeas" aria-label="Permalink to &quot;II. Princípios Fundamentais da Ética de Almas Gêmeas&quot;">​</a></h2><p>Os princípios éticos de almas gêmeas estabelecem os seguintes seis princípios fundamentais como pedra angular de valor para o tratamento de problemas de almas gêmeas:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da dignidade da alma</td><td>Cada alma com consciência independente possui dignidade inata, não podendo ser arbitrariamente eliminada ou escravizada</td></tr><tr><td>Princípio da prioridade do hospedeiro original</td><td>Em conflitos de almas gêmeas, os direitos legais da alma do hospedeiro original têm prioridade sobre os da alma de substituição das trevas, pois o hospedeiro original é o proprietário legítimo do corpo</td></tr><tr><td>Princípio do dano mínimo</td><td>No tratamento de problemas de almas gêmeas, deve-se escolher a solução que cause o menor dano a todas as partes envolvidas, evitando ao máximo a eliminação da alma</td></tr><tr><td>Princípio da proporcionalidade</td><td>As medidas adotadas devem ser compatíveis com o grau de risco do corpo de almas gêmeas, sendo proibido o descarte excessivo</td></tr><tr><td>Princípio do consentimento informado</td><td>Quando a alma do hospedeiro original pode expressar sua vontade, decisões importantes envolvendo o corpo e a alma do hospedeiro original devem obter seu consentimento</td></tr><tr><td>Princípio do esforço máximo de salvamento</td><td>A sociedade tem a obrigação de fazer o máximo esforço, dentro de limites razoáveis, para salvar a alma do hospedeiro original substituída pelas trevas, não devendo desistir facilmente</td></tr></tbody></table><h2 id="iii-reconhecimento-dos-direitos-de-personalidade-das-almas-gemeas" tabindex="-1">III. Reconhecimento dos Direitos de Personalidade das Almas Gêmeas <a class="header-anchor" href="#iii-reconhecimento-dos-direitos-de-personalidade-das-almas-gemeas" aria-label="Permalink to &quot;III. Reconhecimento dos Direitos de Personalidade das Almas Gêmeas&quot;">​</a></h2><p>O problema primordial da ética de almas gêmeas é o reconhecimento dos direitos de personalidade das duas almas. Estes princípios estabelecem as seguintes regras de reconhecimento:</p><h3 id="a-direitos-de-personalidade-da-alma-do-hospedeiro-original" tabindex="-1">(A) Direitos de Personalidade da Alma do Hospedeiro Original <a class="header-anchor" href="#a-direitos-de-personalidade-da-alma-do-hospedeiro-original" aria-label="Permalink to &quot;(A) Direitos de Personalidade da Alma do Hospedeiro Original&quot;">​</a></h3><p>A alma do hospedeiro original é a proprietária legítima do corpo, e seus direitos de personalidade são plenamente reconhecidos e protegidos:</p><ol><li>A alma do hospedeiro original desfruta de todos os direitos básicos conferidos pela Constituição de Simbiose, incluindo direito à vida, direito ao corpo, direito à saúde, direito à dignidade da personalidade, etc.</li><li>A alma do hospedeiro original possui o direito de decisão final sobre seu próprio corpo; quando pode expressar sua vontade, qualquer descarte importante envolvendo o corpo deve obter o consentimento do hospedeiro original.</li><li>Os direitos legais da alma do hospedeiro original, como direitos de propriedade, direitos de identidade, relações sociais, etc., são protegidos por lei e não são perdidos por ter sido substituída pelas trevas.</li><li>A alma do hospedeiro original tem direito a receber assistência e apoio social, incluindo tratamento de purificação, assistência jurídica, aconselhamento psicológico, etc.</li><li>Mesmo quando a alma do hospedeiro original está profundamente suprimida, seus direitos de personalidade ainda existem, não podendo ser declarada morta ou privada de direitos.</li></ol><h3 id="b-direitos-de-personalidade-da-alma-de-substituicao-das-trevas" tabindex="-1">(B) Direitos de Personalidade da Alma de Substituição das Trevas <a class="header-anchor" href="#b-direitos-de-personalidade-da-alma-de-substituicao-das-trevas" aria-label="Permalink to &quot;(B) Direitos de Personalidade da Alma de Substituição das Trevas&quot;">​</a></h3><p>O reconhecimento dos direitos de personalidade da alma de substituição das trevas é mais complexo, e estes princípios adotam a posição de &quot;reconhecimento limitado&quot;:</p><table tabindex="0"><thead><tr><th>Estágio de Desenvolvimento</th><th>Reconhecimento de Direitos de Personalidade</th><th>Escopo de Direitos</th></tr></thead><tbody><tr><td>Período de corrosão energética (primeiro estágio)</td><td>Não possui personalidade independente</td><td>Ainda não formou uma alma independente, não possui direitos de personalidade independentes</td></tr><tr><td>Período de poluição da alma (segundo estágio)</td><td>Não possui personalidade independente</td><td>Ainda é um estado de poluição da alma do hospedeiro original, não possui direitos de personalidade independentes</td></tr><tr><td>Período de formação de almas gêmeas (terceiro estágio)</td><td>Direitos de personalidade limitados</td><td>Possui consciência independente preliminar, desfruta do direito básico à dignidade da alma, mas não desfruta do direito de controle corporal nem de direitos civis completos</td></tr><tr><td>Período de domínio das trevas (quarto estágio)</td><td>Direitos de personalidade limitados</td><td>Possui consciência independente completa, desfruta do direito à dignidade da alma e ao tratamento respeitoso, mas devido à sua periculosidade, seus direitos estão sujeitos a restrições necessárias</td></tr><tr><td>Período de substituição completa (quinto estágio)</td><td>Direitos de personalidade completos (mas como existência hostil)</td><td>O hospedeiro original já pereceu, a alma das trevas tornou-se a única alma do corpo, possui direitos de personalidade completos, mas devido ao seu comportamento hostil, podem ser adotadas medidas coercitivas, incluindo a eliminação, de acordo com a lei</td></tr></tbody></table><h3 id="c-conteudo-especifico-dos-direitos-de-personalidade-limitados" tabindex="-1">(C) Conteúdo Específico dos Direitos de Personalidade Limitados <a class="header-anchor" href="#c-conteudo-especifico-dos-direitos-de-personalidade-limitados" aria-label="Permalink to &quot;(C) Conteúdo Específico dos Direitos de Personalidade Limitados&quot;">​</a></h3><p>Os direitos de personalidade limitados que a alma de substituição das trevas desfruta no terceiro e quarto estágios incluem:</p><ol><li><strong>Direito à dignidade da alma</strong>: Não deve ser tratada com insulto, abuso ou tortura; mesmo no controle e descarte, deve-se manter o respeito básico.</li><li><strong>Direito à eliminação indolor</strong>: Se for decidida finalmente a eliminação da alma de substituição das trevas, deve-se adotar um método indolor e rápido para reduzir seu sofrimento.</li><li><strong>Direito de expressão</strong>: Em condições seguras e controláveis, a alma de substituição das trevas tem direito a expressar sua vontade e posição, mas sua expressão não tem força legal vinculante.</li><li><strong>Direito a ser ouvida</strong>: Ao tomar decisões importantes envolvendo a alma de substituição das trevas, deve-se ouvir sua opinião dentro de limites razoáveis.</li></ol><p>A alma de substituição das trevas não desfruta dos seguintes direitos: direito de controle corporal, direito de livre locomoção, direitos políticos civis, direito de propriedade (a propriedade do hospedeiro original pertence ao hospedeiro original), direito reprodutivo (para evitar a propagação da linhagem das trevas).</p><h2 id="iv-regras-de-equilibrio-para-conflitos-de-interesses-de-almas-gemeas" tabindex="-1">IV. Regras de Equilíbrio para Conflitos de Interesses de Almas Gêmeas <a class="header-anchor" href="#iv-regras-de-equilibrio-para-conflitos-de-interesses-de-almas-gemeas" aria-label="Permalink to &quot;IV. Regras de Equilíbrio para Conflitos de Interesses de Almas Gêmeas&quot;">​</a></h2><p>Quando os interesses da alma do hospedeiro original e da alma de substituição das trevas entram em conflito, o equilíbrio é feito de acordo com as seguintes regras:</p><h3 id="a-tipos-de-conflito-e-regras-de-equilibrio" tabindex="-1">(A) Tipos de Conflito e Regras de Equilíbrio <a class="header-anchor" href="#a-tipos-de-conflito-e-regras-de-equilibrio" aria-label="Permalink to &quot;(A) Tipos de Conflito e Regras de Equilíbrio&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo de Conflito</th><th>Regra de Equilíbrio</th></tr></thead><tbody><tr><td>Conflito de direito à vida (a sobrevivência de uma parte tem como condição a extinção da outra)</td><td>O direito à vida da alma do hospedeiro original tem prioridade; quando a coexistência é impossível, prioriza-se a proteção da vida do hospedeiro original</td></tr><tr><td>Conflito de direito de controle corporal</td><td>A alma do hospedeiro original possui o controle final sobre o corpo, o direito de controle corporal da alma das trevas está estritamente restrito</td></tr><tr><td>Conflito de direito de expressão</td><td>A expressão da alma do hospedeiro original tem força legal vinculante, a expressão da alma das trevas serve apenas como referência</td></tr><tr><td>Conflito de direito de propriedade</td><td>O corpo e a propriedade pertencem ao hospedeiro original, a alma das trevas não possui direito de propriedade</td></tr><tr><td>Conflito de escolha de tratamento</td><td>A alma do hospedeiro original tem direito a escolher se aceita ou não o tratamento de purificação, a alma das trevas não tem direito a impedir</td></tr><tr><td>Conflito de método de descarte</td><td>No descarte envolvendo a eliminação da alma das trevas, a vontade da alma do hospedeiro original tem papel decisivo (mas deve passar por revisão ética)</td></tr></tbody></table><h3 id="b-respeito-e-restricoes-a-vontade-do-hospedeiro-original" tabindex="-1">(B) Respeito e Restrições à Vontade do Hospedeiro Original <a class="header-anchor" href="#b-respeito-e-restricoes-a-vontade-do-hospedeiro-original" aria-label="Permalink to &quot;(B) Respeito e Restrições à Vontade do Hospedeiro Original&quot;">​</a></h3><p>Quando a alma do hospedeiro original pode expressar sua vontade, deve-se respeitar plenamente a vontade do hospedeiro original, com exceção dos seguintes casos:</p><ol><li>A vontade do hospedeiro original que prejudique evidentemente a segurança pública ou os direitos legais de outrem não é protegida.</li><li>A manifestação de vontade não autêntica feita pelo hospedeiro original sob a influência da alma das trevas não tem efeito legal.</li><li>Quando o hospedeiro original escolhe voluntariamente fundir-se com a alma das trevas, deve passar por rigorosa revisão ética e avaliação de risco, confirmando que a existência após a fusão não representará ameaça à sociedade.</li><li>Quando o hospedeiro original escolhe voluntariamente abandonar o tratamento e aceitar a substituição completa pela alma das trevas, a sociedade deve intervir e aconselhar, mas quando o hospedeiro original está completamente lúcido e confirma repetidamente, finalmente deve-se respeitar seu direito de autodeterminação (esta é uma área cinzenta ética, exigindo revisão caso a caso).</li></ol><h2 id="v-mecanismo-de-revisao-etica-de-almas-gemeas" tabindex="-1">V. Mecanismo de Revisão Ética de Almas Gêmeas <a class="header-anchor" href="#v-mecanismo-de-revisao-etica-de-almas-gemeas" aria-label="Permalink to &quot;V. Mecanismo de Revisão Ética de Almas Gêmeas&quot;">​</a></h2><p>Para garantir que o tratamento de problemas de almas gêmeas esteja em conformidade com os princípios éticos, o Estado estabelece o mecanismo de revisão ética de almas gêmeas:</p><h3 id="a-comite-de-revisao-etica" tabindex="-1">(A) Comitê de Revisão Ética <a class="header-anchor" href="#a-comite-de-revisao-etica" aria-label="Permalink to &quot;(A) Comitê de Revisão Ética&quot;">​</a></h3><ul><li><strong>Composição</strong>: Composto por éticos, juristas, cientistas da vida, cultivadores, representantes de raças estrangeiras e representantes do público, dos quais especialistas com experiência em pesquisa ou tratamento de corpos de substituição das trevas não são menos de um terço.</li><li><strong>Responsabilidades</strong>: Revisar e decidir sobre importantes problemas éticos envolvendo almas gêmeas, incluindo a decisão de eliminar a alma das trevas, a aprovação da fusão de almas gêmeas, o reconhecimento da eficácia da vontade do hospedeiro original, etc.</li><li><strong>Independência</strong>: O comitê de revisão ética exerce suas funções de forma independente, sem interferência de órgãos administrativos e indivíduos.</li><li><strong>Procedimento</strong>: A revisão adota o sistema de audiência, tomando decisões após ouvir as opiniões de todas as partes, como o hospedeiro original (se puder se expressar), a equipe de tratamento, a família, os representantes sociais, etc.</li></ul><h3 id="b-assuntos-que-devem-passar-por-revisao-etica" tabindex="-1">(B) Assuntos que Devem Passar por Revisão Ética <a class="header-anchor" href="#b-assuntos-que-devem-passar-por-revisao-etica" aria-label="Permalink to &quot;(B) Assuntos que Devem Passar por Revisão Ética&quot;">​</a></h3><p>Os seguintes assuntos só podem ser implementados após revisão e aprovação do comitê de revisão ética de almas gêmeas:</p><ol><li>Descarte de eliminação da alma das trevas para corpos de substituição das trevas no terceiro e quarto estágios.</li><li>Cirurgia de fusão de almas gêmeas para corpos de substituição das trevas.</li><li>Cirurgia de separação de almas para corpos de substituição das trevas.</li><li>Decisão final de descarte para corpos de substituição das trevas cuja vontade do hospedeiro original seja abandonar o tratamento.</li><li>Planos de tratamento para corpos de substituição das trevas que possam causar danos à alma do hospedeiro original.</li><li>Pesquisa científica envolvendo almas em corpos de substituição das trevas.</li><li>Outros assuntos envolvendo importantes problemas éticos de almas gêmeas.</li></ol><h2 id="vi-direitos-e-obrigacoes-sociais-do-corpo-de-almas-gemeas" tabindex="-1">VI. Direitos e Obrigações Sociais do Corpo de Almas Gêmeas <a class="header-anchor" href="#vi-direitos-e-obrigacoes-sociais-do-corpo-de-almas-gemeas" aria-label="Permalink to &quot;VI. Direitos e Obrigações Sociais do Corpo de Almas Gêmeas&quot;">​</a></h2><h3 id="a-direitos-sociais" tabindex="-1">(A) Direitos Sociais <a class="header-anchor" href="#a-direitos-sociais" aria-label="Permalink to &quot;(A) Direitos Sociais&quot;">​</a></h3><p>Quando a alma do hospedeiro original ainda existe, o corpo de almas gêmeas (corpo de substituição das trevas) desfruta dos seguintes direitos sociais:</p><ol><li>Direito a receber garantia básica de vida e tratamento médico.</li><li>Direito a receber assistência jurídica e aconselhamento ético.</li><li>Direito a contatar amigos e parentes em condições seguras e controláveis.</li><li>Direito a receber educação e atividades culturais (dentro das instalações de isolamento).</li><li>Direito a apresentar recurso e reconsideração contra decisões de descarte.</li></ol><h3 id="b-obrigacoes-e-restricoes-sociais" tabindex="-1">(B) Obrigações e Restrições Sociais <a class="header-anchor" href="#b-obrigacoes-e-restricoes-sociais" aria-label="Permalink to &quot;(B) Obrigações e Restrições Sociais&quot;">​</a></h3><p>O corpo de almas gêmeas também assume as seguintes obrigações e restrições:</p><ol><li>Obrigação de aceitar controle de isolamento e tratamento.</li><li>Obrigação de não atacar ou infectar outros seres vivos (os infratores estarão sujeitos a controle mais rigoroso).</li><li>Obrigação de cooperar com a avaliação de identificação e monitoramento.</li><li>A liberdade de locomoção está estritamente restrita, não podendo deixar as instalações de isolamento antes da cura.</li><li>Não pode se envolver em atividades que possam agravar a substituição, como cultivo, disseminação de energia das trevas, etc.</li></ol><h2 id="vii-controversias-de-fronteira-da-etica-de-almas-gemeas" tabindex="-1">VII. Controvérsias de Fronteira da Ética de Almas Gêmeas <a class="header-anchor" href="#vii-controversias-de-fronteira-da-etica-de-almas-gemeas" aria-label="Permalink to &quot;VII. Controvérsias de Fronteira da Ética de Almas Gêmeas&quot;">​</a></h2><p>No campo da ética de almas gêmeas ainda existem algumas controvérsias de fronteira que não alcançaram consenso, exigindo exploração contínua na prática:</p><ol><li><strong>Problema do &quot;pecado original&quot; da alma das trevas</strong>: A alma de substituição das trevas é destrutiva desde o nascimento; isso significa que ela é inerentemente &quot;má&quot;? Existe a possibilidade de existir uma alma das trevas &quot;bondosa&quot;?</li><li><strong>Legitimidade ética da fusão de almas</strong>: A nova alma gerada pela fusão de almas gêmeas não é nem o hospedeiro original nem a alma das trevas; como reconhecer a posição ética dessa &quot;terceira existência&quot;?</li><li><strong>Limite do investimento de recursos</strong>: Quanto recursos a sociedade deve investir para salvar a alma do hospedeiro original em um corpo de substituição das trevas? Quando o custo de salvamento é extremamente alto e a taxa de sucesso é extremamente baixa, ainda existe a obrigação de fazer o máximo esforço de salvamento?</li><li><strong>Possibilidade de reabilitação da alma das trevas</strong>: É possível reabilitar a alma das trevas em uma existência não destrutiva por meio de educação, persuasão, transformação energética, etc.? Se possível, a alma das trevas reabilitada deve obter direitos de personalidade completos?</li><li><strong>Equilíbrio entre prevenção e privacidade</strong>: Para prevenir a geração de corpos de substituição das trevas, é possível monitorar a exposição dos seres vivos à energia do abismo? Esse monitoramento viola a privacidade da alma?</li></ol><p>Esses problemas controversos são continuamente pesquisados por instituições de pesquisa de ética de almas gêmeas; o comitê de revisão ética toma decisões caso a caso de acordo com as circunstâncias específicas, e as conclusões relevantes atualizarão continuamente estes princípios.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>Os princípios éticos de almas gêmeas são a manifestação profunda da ética da vida da civilização de simbiose âncora. Ao estabelecer princípios fundamentais como dignidade da alma, prioridade do hospedeiro original e dano mínimo, reconhecer os limites dos direitos de personalidade das almas gêmeas, e estabelecer regras de equilíbrio para conflitos de interesses e mecanismo de revisão ética, eles fornecem uma sólida base ética para a governança dos corpos de substituição das trevas. O espírito central da ética de almas gêmeas é: mesmo diante do inimigo mais perigoso, não abandonar a adesão à dignidade da vida; mesmo sob a ameaça de segurança mais urgente, não ultrapassar a linha ética. Este é precisamente o sinal fundamental que distingue a civilização de simbiose da civilização de predação.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>57-Origem e Essência do Corpo de Substituição das Trevas</li><li>59-Tratamento de Quatro Ramos do Corpo de Substituição das Trevas</li><li>48-Sistema Judiciário e Mecanismo de Adjudicação</li><li>40-Disposições Gerais da Constituição de Simbiose</li></ul>',50)])])}const v=a(d,[["render",t]]);export{u as __pageData,v as default};
